"""List tool_use calls (name + short input summary) between two line numbers of a transcript.

Usage: python3 -I tools.py <transcript> FROM TO [char_limit]
"""
import json
import sys

path, lo, hi = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
limit = int(sys.argv[4]) if len(sys.argv) > 4 else 300
for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    if not (lo <= n <= hi):
        continue
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    if not isinstance(ev, dict):
        continue
    msg = ev.get("message") if isinstance(ev.get("message"), dict) else {}
    content = msg.get("content")
    if not isinstance(content, list):
        continue
    for b in content:
        if not isinstance(b, dict):
            continue
        if b.get("type") == "tool_use":
            inp = b.get("input") or {}
            print(f"L{n} TOOL_USE {b.get('name')} id={b.get('id')} :: {json.dumps(inp, ensure_ascii=False)[:limit]}")
        elif b.get("type") == "tool_result":
            parts = b.get("content")
            if isinstance(parts, str):
                t = parts
            elif isinstance(parts, list):
                t = " | ".join(
                    (p.get("text", "") if p.get("type") == "text" else f"<{p.get('type')}>")
                    for p in parts
                    if isinstance(p, dict)
                )
            else:
                t = ""
            print(f"L{n} TOOL_RESULT id={b.get('tool_use_id')} :: {t[:limit]!r}")

