"""Print the full input of every tool_use on the given transcript line numbers.

Usage: python3 -I dump_tool.py <transcript> LINE [LINE ...]
For Write: prints file_path then content verbatim. For Bash: prints the command.
For others: prints JSON input.
"""
import json
import sys

path = sys.argv[1]
wanted = {int(x) for x in sys.argv[2:]}
for n, line in enumerate(open(path, encoding="utf-8", errors="replace"), 1):
    if n not in wanted:
        continue
    ev = json.loads(line)
    msg = ev.get("message") if isinstance(ev.get("message"), dict) else {}
    for b in msg.get("content") or []:
        if not (isinstance(b, dict) and b.get("type") == "tool_use"):
            continue
        inp = b.get("input") or {}
        name = b.get("name")
        print(f"===== L{n} {name} =====")
        if name == "Write":
            print(f"file_path: {inp.get('file_path')}")
            print(inp.get("content", ""))
        elif name == "Edit":
            print(f"file_path: {inp.get('file_path')}")
            print("--- old_string:")
            print(inp.get("old_string", ""))
            print("--- new_string:")
            print(inp.get("new_string", ""))
        elif name == "Bash":
            print(inp.get("command", ""))
        else:
            print(json.dumps(inp, ensure_ascii=False, indent=1))
        print()

