for n, line in enumerate(open(sys.argv[1], encoding="utf-8", errors="replace"), 1):
    ev = json.loads(line)
    if ev.get("type") == "queue-operation" and ev.get("operation") == "enqueue" and ev.get("content"):
        queued.append((n, ev["content"]))
    if ev.get("type") == "user" and not ev.get("isMeta"):
        c = (ev.get("message") or {}).get("content")
        texts = [c] if isinstance(c, str) else [b.get("text","") for b in c or [] if isinstance(b, dict) and b.get("type")=="text"]
        for t in texts:
            if t.strip() and not t.lstrip().startswith("<"):
                delivered.append((n, t))
print(len(queued), len(delivered))
for (qn, q), (dn, d) in zip(queued, delivered):
    print(qn, dn, "same" if q.strip() == d.strip() else f"DIFF q={len(q)} d={len(d)}")
